export const useExtensionAgent = <TError = ErrorType<void>,
    TContext = unknown>(options?: { mutation?:UseMutationOptions<Awaited<ReturnType<typeof extensionAgent>>, TError,{data: BodyType<ExtensionAgentInput>}, TContext>, request?: SecondParameter<typeof customFetch>}
 ): UseMutationResult<
        Awaited<ReturnType<typeof extensionAgent>>,
        TError,
        {data: BodyType<ExtensionAgentInput>},
        TContext
      > => {
      return useMutation(getExtensionAgentMutationOptions(options));
    }

